"""mnist_cnn — PyTorch model generated by AI Made Easy.

Input shape:  (batch, 1, 28, 28)
Output shape: (batch, 10)
Trainable parameters: 5,130
"""
from __future__ import annotations

import torch
import torch.nn as nn


class MnistCnn(nn.Module):
    """mnist_cnn: (batch, 1, 28, 28) -> (batch, 10)."""

    def __init__(self) -> None:
        super().__init__()
        self.conv2d_1 = nn.Conv2d(in_channels=1, out_channels=16, kernel_size=3, stride=1, padding=1)
        self.relu_1 = nn.ReLU()
        self.maxpool2d_1 = nn.MaxPool2d(kernel_size=2, stride=2, padding=0)
        self.conv2d_2 = nn.Conv2d(in_channels=16, out_channels=32, kernel_size=3, stride=1, padding=1)
        self.relu_2 = nn.ReLU()
        self.dense_1 = nn.Linear(in_features=32, out_features=10, bias=True)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.conv2d_1(x)
        x = self.relu_1(x)
        x = self.maxpool2d_1(x)
        x = self.conv2d_2(x)
        x = self.relu_2(x)
        x = torch.mean(x, dim=(2, 3))
        x = self.dense_1(x)
        return x


def build_model() -> MnistCnn:
    """Construct a freshly initialised model."""
    return MnistCnn()


if __name__ == "__main__":
    model = build_model()
    print(model)
    n_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"trainable parameters: {n_params:,}")
    x = torch.randn(2, 1, 28, 28)
    model.eval()
    with torch.no_grad():
        y = model(x)
    print("input shape: ", tuple(x.shape))
    print("output shape:", tuple(y.shape))
